`timescale			    1ns/1ps
`default_nettype		none

`define     PED(clk, sig, pulse)    reg last_``sig``; always @(posedge clk) last_``sig`` <= sig; assign pulse = sig & ~last_``sig``;
`define     NED(clk, sig, pulse)    reg last_``sig``; always @(posedge clk) last_``sig`` <= sig; assign pulse = ~sig & last_``sig``;

/*
    Brute-force Synchronizer
*/
// From efabless/EF_IP_UTIL hdl/ef_util_lib.v (commit a2b3fb6): the modules EF_UART needs.
module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk,
    input wire in,
    output wire out
);

    reg [NUM_STAGES-1:0] sync;

    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0], in};

    assign out = sync[NUM_STAGES-1];

endmodule

module ef_util_ticker #(parameter W=8) (
    input   wire            clk, 
    input   wire            rst_n,
    input   wire            en,
    input   wire [W-1:0]    clk_div,
    output  wire            tick
);

    reg [W-1:0] counter;
    wire        counter_is_zero = (counter == 'b0);
    wire        tick_w;
    reg         tick_reg;

    always @(posedge clk, negedge rst_n)
        if(~rst_n)
            counter <=  'b0;
        else if(en) 
            if(counter_is_zero)
                counter <=  clk_div;
            else
                counter <=  counter - 'b1; 

	assign tick_w = (clk_div == 'b0)  ?   1'b1 : counter_is_zero;

    always @(posedge clk or negedge rst_n)
        if(!rst_n)
            tick_reg <= 1'b0;
        else if(en)
            tick_reg <= tick_w;
        else
            tick_reg <= 0;

    assign tick = tick_reg;

endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input   wire    clk,
    input   wire    rst_n,
    input   wire    in,
    input   wire    en,
    output  reg     out
);

    reg [N-1:0] shifter;
    wire        tick;

    ef_util_ticker ticker (
        .clk(clk),
        .rst_n(rst_n),
	.en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk, negedge rst_n)
        if(!rst_n)
            shifter <= 'b0;
        else if(tick)
            shifter <= {shifter[N-2:0], in};

    wire all_ones   = & shifter;
    wire all_zeros  = ~| shifter;

    always @(posedge clk, negedge rst_n)
        if(!rst_n)
            out <= 1'b0;
        else
            if(all_ones) 
                out <= 1'b1;
            else if(all_zeros) 
                out <= 1'b0;
endmodule

module ef_util_fifo #(parameter DW=8, AW=4)(
    input   wire            clk,
    input   wire            rst_n,
    input   wire            rd,
    input   wire            wr,
    input   wire            flush,
    input   wire [DW-1:0]   wdata,
    output  wire            empty,
    output  wire            full,
    output  wire [DW-1:0]   rdata,
    output  wire [AW-1:0]   level    
);
  reg [DW-1:0] mem [0:(1<<AW)-1];
  reg [AW-1:0] rptr, wptr;
  reg [AW-1:0] level_reg;
  reg full_reg;
  wire empty_i = (level_reg == {AW{1'b0}}) && !full_reg;
  wire wr_ok = wr && !full_reg;
  // A simultaneous operation on an empty FIFO advances both pointers.  This
  // is useful for the FIFO users, which may issue read and write strobes
  // without first having to special case the empty state.
  wire rd_ok = rd && (!empty_i || wr_ok);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rptr <= 0; wptr <= 0; level_reg <= 0; full_reg <= 1'b0;
    end else if (flush) begin
      rptr <= 0; wptr <= 0; level_reg <= 0; full_reg <= 1'b0;
    end else begin
      if (wr_ok) begin mem[wptr] <= wdata; wptr <= wptr + 1'b1; end
      if (rd_ok) rptr <= rptr + 1'b1;
      if (wr_ok && !rd_ok) begin
        level_reg <= level_reg + 1'b1;
        if ((wptr + 1'b1) == rptr) full_reg <= 1'b1;
      end else if (!wr_ok && rd_ok) begin
        level_reg <= level_reg - 1'b1;
        full_reg <= 1'b0;
      end
      if (wr_ok && rd_ok) begin
        // level and full status are unchanged for a genuine replacement.
        if (empty_i) begin level_reg <= level_reg; full_reg <= 1'b0; end
      end
    end
  end
  assign rdata = mem[rptr];
  assign empty = empty_i;
  assign full = full_reg;
  assign level = level_reg;
endmodule

